	auto n = r | get_length<'i'>();
	const num_t base = static_cast<num_t>(n + 1);

	// Single traverser loop over 'i'
	traverser(r).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		r[state] = base - static_cast<num_t>(i);
