void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// pseudo-structure for the k loop
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	const num_t one  = SCALAR_VAL(1.0);
	const num_t zero = SCALAR_VAL(0.0);

	#pragma scop
	// Initial step:
	//   y[0] = -r[0];
	//   beta = 1.0;
	//   alpha = -r[0];
	auto idx0 = noarr::idx<'i'>(0);
	num_t r0 = r[idx0];

	y[idx0] = -r0;
	beta    = one;
	alpha   = -r0;

	// Main Durbin recurrence:
	//   for (k = 1; k < n; k++) { ... }
	noarr::traverser(k_structure)
		.order(noarr::slice<'k'>(1, n - 1)) // iterate k = 1 .. n-1
		.template for_dims<'k'>([&](auto k_trav) {
			auto k_state = k_trav.state();
			std::size_t k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			const num_t alpha_sq = alpha * alpha;
			beta = (one - alpha_sq) * beta;

			// sum = 0.0;
			sum = zero;

			// sum = sum_{i=0}^{k-1} r[k-i-1] * y[i];
			// We traverse y over i = 0 .. k-1 and access r in reverse order.
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k))
				.for_each([&](auto i_state) {
					std::size_t i = noarr::get_index<'i'>(i_state);

					auto r_state = noarr::idx<'i'>(k - i - 1);
					sum += r[r_state] * y[i_state];
				});

