			auto rk_state = noarr::idx<'i'>(k);
			alpha = -(r[rk_state] + sum) / beta;

			// Original algorithm:
			//   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
			//   for (i = 0; i < k; i++) y[i] = z[i];
			//
			// This is equivalent to:
			//   new_y[i] = old_y[i] + alpha * old_y[k-1-i]  for all i in [0, k-1]
			//
			// We implement this in-place, without the temporary array z, by
			// updating symmetric pairs (i, j) where j = k-1-i:
			//
			//   y_i' = y_i + alpha * y_j
			//   y_j' = y_j + alpha * y_i
			//
			// For the center element when k is odd (i == j), we get:
			//   y_i' = y_i + alpha * y_i = (1 + alpha) * y_i
