				.order(noarr::slice<'i'>(0, half))
				.for_each([&](auto i_state) {
					std::size_t i = noarr::get_index<'i'>(i_state);
					std::size_t j = k - 1 - i; // partner index

					// Old values of the pair
					num_t yi_old = y[i_state];

					if (i == j) {
						// Center element in case of odd k
						y[i_state] = yi_old + alpha * yi_old;
					} else {
						// Symmetric pair (i, j) with i < j, processed exactly once
						auto j_state = noarr::idx<'i'>(j);
