	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

#pragma scop
	// Initial step:
	// y[0] = -r[0];
	auto i0 = noarr::idx<'i'>(0);
	y[i0] = -r[i0];

	beta = SCALAR_VAL(1.0);
	alpha = -r[i0];

