			//   For i < j = k-1-i:
			//       (y[i], y[j]) :=
			//         ( y[i] + alpha*y[j],
			//           y[j] + alpha*y[i] )
			//   For odd k, handle center i=j=(k-1)/2 separately.
			//
			// This is algebraically equivalent, because both new
			// values depend only on the original pair (y[i], y[j]).
