				.order(noarr::slice<'i'>(0, half))
				.for_each([&](auto i_state) {
					auto i = noarr::get_index<'i'>(i_state);
					auto j = k - i - 1; // matching index from the other end

					auto j_state = noarr::idx<'i'>(j);

					// Read old values
					num_t yi = y[i_state];
					num_t yj = y[j_state];

					// Write new values in-place
					y[i_state] = yi + alpha * yj;
					y[j_state] = yj + alpha * yi;
				});

			// If k is odd, there is one center element not covered
			// by the pairwise loop: i = j = k/2.
