	noarr::traverser(k_structure)
		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			auto k_state = k_trav.state();
			const std::size_t k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			const num_t alpha_sq = alpha * alpha;
			beta = (one - alpha_sq) * beta;

			// sum = 0.0;
			sum = zero;

			// ------------------------------------------------------------------
			// Efficient computation of:
			//   for (i = 0; i < k; i++) sum += r[k - i - 1] * y[i];
			//
			// We process pairs (i, j = k - i - 1), i < j, in one pass:
			//   contribution from i: r[j] * y[i]
			//   contribution from j: r[i] * y[j]
			// so:
			//   sum += r[j] * y[i] + r[i] * y[j];
			//
			// If k is odd, the middle element i == j == (k - 1)/2 is handled
			// separately afterwards.
			// ------------------------------------------------------------------
			const std::size_t half = k / 2;

