			// This exactly matches what the z-based update computes for both
			// indices, while only using a couple of scalars as temporaries.
			// The center element (for odd k) satisfies i == j and reduces to
			//   y'[i] = (1 + alpha) * yi.
			// ------------------------------------------------------------------

			// Process pairs (i, j), i < j
			noarr::traverser(p_structure)
				.order(noarr::slice<'p'>(0, half))
				.for_each([&](auto p_state) {
					const std::size_t p = noarr::get_index<'p'>(p_state);
					const std::size_t i = p;
					const std::size_t j = k - p - 1;

					auto i_state = noarr::idx<'i'>(i);
					auto j_state = noarr::idx<'i'>(j);

					const num_t yi = y[i_state];
					const num_t yj = y[j_state];

					y[i_state] = yi + alpha * yj;
					y[j_state] = yj + alpha * yi;
				});

			// Center element when k is odd: i == j == (k-1)/2
			if (k & 1u) {
				const std::size_t mid = half;
				auto mid_state = noarr::idx<'i'>(mid);
				const num_t ymid = y[mid_state];
				y[mid_state] = ymid + alpha * ymid; // (1 + alpha) * old ymid
			}

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
	#pragma endscop
}

} // namespace

