#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "durbin.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();

struct tuning {
	// 1D layout over dimension 'i'
	DEFINE_PROTO_STRUCT(r_layout, i_vec);
	DEFINE_PROTO_STRUCT(y_layout, i_vec);
} tuning;

// initialization function: r[i] = n + 1 - i
void init_array(auto r) {
	using namespace noarr;

	auto n = r | get_length<'i'>();

	traverser(r).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		r[state] = (num_t)(n + 1 - i);
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	const std::size_t n = r | get_length<'i'>();

	// common scalar constants (avoid repeated SCALAR_VAL conversions)
	const num_t one  = SCALAR_VAL(1.0);
	const num_t zero = SCALAR_VAL(0.0);

	// pseudo-structure for the k loop
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	#pragma scop
	// y[0] = -r[0];
	y[noarr::idx<'i'>(0)] = -r[noarr::idx<'i'>(0)];
	beta = one;
	alpha = -r[noarr::idx<'i'>(0)];

	// for (k = 1; k < n; k++)
	noarr::traverser(k_structure)
		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			// current k index
			auto k_state = k_trav.state();
			const std::size_t k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			beta *= (one - alpha * alpha);

			// sum = 0.0;
			sum = zero;

			// for (i = 0; i < k; i++) sum += r[k - i - 1] * y[i];
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k))
				.for_each([&](auto i_state) {
					const std::size_t i = noarr::get_index<'i'>(i_state);
					auto r_state = noarr::idx<'i'>(k - i - 1);
					sum += r[r_state] * y[i_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			// Optimized in-place update of y[0..k-1]:
			// Original code used a temporary z[] and then copied it back to y[].
			// Here we exploit symmetry of indices (i, j = k-1-i) and update
			// both y[i] and y[j] at once from the original values, which
			// preserves semantics but halves memory traffic and removes z[].
			const std::size_t half = k / 2;

			// Process disjoint pairs (i, j = k-1-i)
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, half))
				.for_each([&](auto i_state) {
					const std::size_t i = noarr::get_index<'i'>(i_state);
					const std::size_t j = k - 1 - i;
					auto j_state = noarr::idx<'i'>(j);

					const num_t yi = y[i_state];
					const num_t yj = y[j_state];

					// z[i] = y[i] + alpha * y[k - i - 1];
					// z[j] = y[j] + alpha * y[k - j - 1] = y[j] + alpha * y[i];
					// y[:] = z[:] in-place for the pair
					y[i_state] = yi + alpha * yj;
					y[j_state] = yj + alpha * yi;
				});

			// If k is odd, handle the middle element i == j == k/2,
			// which maps to itself in the original algorithm:
			// z[mid] = y[mid] + alpha * y[mid]
			if (k & 1u) {
				const std::size_t mid = half; // since k = 2*half + 1
				auto mid_state = noarr::idx<'i'>(mid);
				const num_t ymid = y[mid_state];
				y[mid_state] = ymid + alpha * ymid;
			}

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n);

	auto r = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);

	// initialize data
	init_array(r.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_durbin(r.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (also prevents dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, y.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
